#include <bits/stdc++.h>
using namespace std;
struct S{uint64_t c,o;bool operator==(S const&z)const{return c==z.c&&o==z.o;}};
struct H{size_t operator()(S const&s)const noexcept{return hash<uint64_t>{}(s.c^(s.o*0x9e3779b97f4a7c15ULL));}};
struct E{int j;long long w;};
int main(){const int W=10,D=576;const long long Q=1000000000000LL;vector<pair<int,int>> cs;map<pair<int,int>,int> id;for(int x=0;x<W;x++)for(int y=0;y<4;y++){id[{x,y}]=cs.size();cs.push_back({x,y});}for(auto u:vector<pair<int,int>>{{-1,1},{W,1},{-1,2},{W,2}}){id[u]=cs.size();cs.push_back(u);}int N=cs.size();vector<vector<int>> nb(N);vector<int> ex(N);vector<pair<int,int>> ed;int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};for(int i=0;i<N;i++){auto[x,y]=cs[i];for(int k=0;k<4;k++){auto it=id.find({x+dx[k],y+dy[k]});if(it==id.end())ex[i]++;else nb[i].push_back(it->second);}for(auto d:vector<pair<int,int>>{{1,0},{0,1}}){auto it=id.find({x+d.first,y+d.second});if(it!=id.end())ed.push_back({i,it->second});}}auto bit=[](int i){return 1ULL<<i;};auto clean=[&](int m){S s{0,0};for(int i=0;i<N;i++)s.c|=bit(i);auto sv=[&](pair<int,int>u){s.c&=~bit(id[u]);};for(int x=0;x<W;x++){sv({x,0});sv({x,1});if(m>>x&1)sv({x,2});}for(auto u:vector<pair<int,int>>{{-1,1},{W,1},{-1,2},{W,2}})sv(u);return s;};unordered_map<S,int,H> mp;vector<S> st;auto add=[&](S s){if(!mp.count(s)){mp.emplace(s,st.size());st.push_back(s);}};for(int m=0;m<(1<<W);m++){S s=clean(m);add(s);for(int i=0;i<N;i++){int v=(s.c&bit(i))?1:((s.o&bit(i))?2:0);for(int nv=0;nv<3;nv++)if(nv!=v){S t=s;t.c&=~bit(i);t.o&=~bit(i);if(nv==1)t.c|=bit(i);if(nv==2)t.o|=bit(i);add(t);}}}if(st.size()!=75776)return 2;int tar=mp.at(clean((1<<W)-1));vector<vector<E>> tr(st.size());vector<long long> fat(st.size()),self(st.size());auto put=[&](int i,S const&t,long long w){auto it=mp.find(t);if(it==mp.end())fat[i]+=w;else if(it->second==i)self[i]+=w;else tr[i].push_back({it->second,w});};for(int si=0;si<(int)st.size();si++){if(si==tar)continue;S s=st[si];uint64_t occ=s.c|s.o;for(int i=0;i<N;i++)if(!(occ&bit(i))){vector<int> os;for(int j:nb[i])if(s.o&bit(j))os.push_back(j);if(os.empty()){S t=s;t.c|=bit(i);put(si,t,D/2);}else{long long w=(D/2)/(long long)os.size();if(w*(long long)os.size()!=D/2)return 3;for(int j:os){S t=s;t.o&=~bit(j);put(si,t,w);}}}for(auto[a,b]:ed)if(!(occ&bit(a))&&!(occ&bit(b))){S p=s;p.o|=bit(a)|bit(b);vector<int>ca,cb;for(int j:nb[a])if(p.c&bit(j))ca.push_back(j);for(int z=0;z<ex[a];z++)ca.push_back(-1);if(ca.empty())ca.push_back(-2);for(int j:nb[b])if(p.c&bit(j))cb.push_back(j);for(int z=0;z<ex[b];z++)cb.push_back(-1);if(cb.empty())cb.push_back(-2);long long w=D/(4LL*ca.size()*cb.size());if(w*4LL*ca.size()*cb.size()!=D)return 4;for(int xa:ca)for(int xb:cb){S t=p;auto r=[&](int q,int ch){if(ch==-2)return;t.o&=~bit(q);if(ch>=0)t.c&=~bit(ch);};r(a,xa);r(b,xb);put(si,t,w);}}long long got=fat[si]+self[si];for(auto e:tr[si])got+=e.w;long long nv=0,ne=0;for(int i=0;i<N;i++)if(!(occ&bit(i)))nv++;for(auto[a,b]:ed)if(!(occ&bit(a))&&!(occ&bit(b)))ne++;if(got!=nv*(D/2)+ne*(D/4))return 5;}vector<long long>lo(st.size()),up(st.size(),Q),nl,nu;lo[tar]=up[tar]=Q;int its=0;for(int it=0;it<5000;it++){nl=lo;nu=up;long long gap=0;for(int i=0;i<(int)st.size();i++)if(i!=tar){long long den=fat[i];for(auto e:tr[i])den+=e.w;if(!den){nl[i]=0;nu[i]=Q;continue;}__int128 a=0,b=0;for(auto e:tr[i]){a+=(__int128)e.w*lo[e.j];b+=(__int128)e.w*up[e.j];}long long l=a/den,u=(b+den-1)/den;if(l<lo[i])l=lo[i];if(u>up[i])u=up[i];if(l>u)return 6;nl[i]=l;nu[i]=u;gap=max(gap,u-l);}lo.swap(nl);up.swap(nu);its=it+1;if(gap<=10)break;}int s0=mp.at(clean(0));cout<<"states="<<st.size()<<"\n"<<"total_rate_rows_checked="<<st.size()-1<<"\n"<<"iterations="<<its<<"\n"<<"start_lo_scaled="<<lo[s0]<<"\n"<<"start_up_scaled="<<up[s0]<<"\n";cout.setf(ios::scientific);cout<<setprecision(12)<<"interval=["<<(double)lo[s0]/Q<<","<<(double)up[s0]/Q<<"]\n";if((__int128)64*up[s0]<(__int128)63*Q)cout<<"NO_LOCAL_63_64\nCERTIFIED_LOCAL_LT_63_64\nPASS\n";else return 7;}
